 private final ArrayList<Medicine> data=FileManager.load(); private final DefaultTableModel model; private final JTable table; private final JTextField search=new JTextField();
 private final JComboBox<String> filter=new JComboBox<>(new String[]{"All medicines","In stock","Low stock","Expiring soon","Expired"});
