 private void nav(JPanel p,String text,Runnable action){JLabel l=new JLabel(text);l.setOpaque(true);l.setMaximumSize(new Dimension(200,43));l.setPreferredSize(new Dimension(200,43));l.setBorder(new EmptyBorder(0,12,0,8));l.setFont(new Font("SansSerif",Font.PLAIN,13));l.setForeground(new Color(200,210,226));l.setBackground(navy);l.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));l.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){action.run();}public void mouseEntered(MouseEvent e){l.setBackground(new Color(39,56,86));}public void mouseExited(MouseEvent e){l.setBackground(navy);}});l.setAlignmentX(LEFT_ALIGNMENT);p.add(l);p.add(Box.createVerticalStrut(7));}
 private JPanel metric(String name,JLabel value,String symbol,Color accent){JPanel p=new JPanel(new BorderLayout(8,9));p.setBackground(Color.WHITE);p.setBorder(new CompoundBorder(new LineBorder(border),new EmptyBorder(15,16,15,15)));JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JLabel n=new JLabel(name);n.setFont(new Font("SansSerif",Font.BOLD,10));n.setForeground(muted);JLabel icon=new JLabel(symbol);icon.setOpaque(true);icon.setBackground(new Color(accent.getRed(),accent.getGreen(),accent.getBlue(),25));icon.setForeground(accent);icon.setHorizontalAlignment(SwingConstants.CENTER);icon.setPreferredSize(new Dimension(32,30));top.add(n,BorderLayout.WEST);top.add(icon,BorderLayout.EAST);value.setFont(new Font("SansSerif",Font.BOLD,28));value.setForeground(navy);p.add(top,BorderLayout.NORTH);p.add(value,BorderLayout.CENTER);return p;}
 private JButton button(String t,Color b,Color f){JButton x=new JButton(t);x.setFont(new Font("SansSerif",Font.BOLD,11));x.setForeground(f);x.setBackground(b);x.setFocusPainted(false);x.setBorder(new CompoundBorder(new LineBorder(b),new EmptyBorder(8,11,8,11)));x.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));return x;}
 private String status(Medicine m){try{LocalDate d=LocalDate.parse(m.getExpiryDate(),fmt),today=LocalDate.now();if(d.isBefore(today))return "EXPIRED";if(!d.isAfter(today.plusDays(30)))return "EXPIRING SOON";if(m.getQuantity()<=m.getMinStock())return "LOW STOCK";return "IN STOCK";}catch(Exception e){return "INVALID DATE";}}
 private void refresh(){if(model==null)return;model.setRowCount(0);String q=search.getText().trim().toLowerCase(Locale.ROOT);String f=(String)filter.getSelectedItem();int ex=0,so=0,lo=0;for(Medicine m:data){String s=status(m);if(s.equals("EXPIRED"))ex++;if(s.equals("EXPIRING SOON"))so++;if(m.getQuantity()<=m.getMinStock())lo++;boolean match=q.isEmpty()||(m.getId()+" "+m.getName()+" "+m.getCompany()+" "+m.getBatchNo()).toLowerCase(Locale.ROOT).contains(q);boolean fm=f==null||f.equals("All medicines")||(f.equals("In stock")&&s.equals("IN STOCK"))||(f.equals("Low stock")&&m.getQuantity()<=m.getMinStock())||(f.equals("Expiring soon")&&s.equals("EXPIRING SOON"))||(f.equals("Expired")&&s.equals("EXPIRED"));if(match&&fm)model.addRow(new Object[]{m.getId(),m.getName(),m.getCompany(),m.getBatchNo(),m.getQuantity(),String.format(Locale.US,"₹%.2f",m.getPrice()),m.getExpiryDate(),s});}total.setText(""+data.size());expired.setText(""+ex);soon.setText(""+so);low.setText(""+lo);statusLine.setText("  Showing "+model.getRowCount()+" of "+data.size()+" medicines  ·  Changes save automatically");}
 private void form(Medicine old){JTextField[] f=new JTextField[8];String[] labels={"Medicine ID *","Medicine Name *","Company","Batch Number","Quantity *","Price (₹) *","Expiry Date (DD/MM/YYYY) *","Minimum Stock *"};String[] vals=old==null?new String[]{"","","","","","","","10"}:new String[]{old.getId(),old.getName(),old.getCompany(),old.getBatchNo(),""+old.getQuantity(),""+old.getPrice(),old.getExpiryDate(),""+old.getMinStock()};JPanel p=new JPanel(new GridLayout(0,2,10,10));p.setBorder(new EmptyBorder(12,12,12,12));for(int i=0;i<8;i++){p.add(new JLabel(labels[i]));f[i]=new JTextField(vals[i],18);f[i].setFont(new Font("SansSerif",Font.PLAIN,12));p.add(f[i]);}f[0].setEditable(old==null);while(true){int r=JOptionPane.showConfirmDialog(this,p,old==null?"Add New Medicine":"Edit Medicine",JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(r!=JOptionPane.OK_OPTION)return;try{String id=f[0].getText().trim(),name=f[1].getText().trim();if(id.isEmpty()||name.isEmpty())throw new IllegalArgumentException("Medicine ID and name are required.");int qty=Integer.parseInt(f[4].getText().trim()),min=Integer.parseInt(f[7].getText().trim());double price=Double.parseDouble(f[5].getText().trim());LocalDate.parse(f[6].getText().trim(),fmt);if(qty<0||min<0||price<0||!Double.isFinite(price))throw new IllegalArgumentException("Quantity, minimum stock and price must be zero or greater.");if(old==null){for(Medicine m:data)if(m.getId().equalsIgnoreCase(id))throw new IllegalArgumentException("Medicine ID already exists.");data.add(new Medicine(id,name,f[2].getText().trim(),f[3].getText().trim(),qty,price,f[6].getText().trim(),min));}else{old.setName(name);old.setCompany(f[2].getText().trim());old.setBatchNo(f[3].getText().trim());old.setQuantity(qty);old.setPrice(price);old.setExpiryDate(f[6].getText().trim());old.setMinStock(min);}save();return;}catch(Exception e){JOptionPane.showMessageDialog(this,"Please check the details.\n"+e.getMessage()+"\nUse date format DD/MM/YYYY.","Invalid data",JOptionPane.WARNING_MESSAGE);}}}
 private Medicine selected(){int row=table.getSelectedRow();if(row<0){message("Select a medicine from the table first.");return null;}String id=String.valueOf(table.getValueAt(table.convertRowIndexToModel(row),0));for(Medicine m:data)if(m.getId().equals(id))return m;return null;}
 private void edit(){Medicine m=selected();if(m!=null)form(m);}private void remove(){Medicine m=selected();if(m!=null&&JOptionPane.showConfirmDialog(this,"Delete "+m.getName()+" ("+m.getId()+")? This cannot be undone.","Confirm delete",JOptionPane.YES_NO_OPTION,JOptionPane.WARNING_MESSAGE)==JOptionPane.YES_OPTION){data.remove(m);save();}}
 private void alerts(){StringBuilder s=new StringBuilder();for(Medicine m:data){String st=status(m);if(!st.equals("IN STOCK"))s.append(m.getName()).append(" [").append(m.getId()).append("] — ").append(st).append(" | Qty: ").append(m.getQuantity()).append(" | Expiry: ").append(m.getExpiryDate()).append("\n");}if(s.length()==0)s.append("No active alerts. All medicines are within the stock and expiry thresholds.");JTextArea a=new JTextArea(s.toString(),13,48);a.setEditable(false);a.setFont(new Font("SansSerif",Font.PLAIN,13));a.setMargin(new Insets(12,12,12,12));JOptionPane.showMessageDialog(this,new JScrollPane(a),"Expiry & Stock Alerts",JOptionPane.INFORMATION_MESSAGE);}
 private void exportCsv(){JFileChooser fc=new JFileChooser();fc.setDialogTitle("Export inventory to CSV");fc.setSelectedFile(new File("medicine-inventory.csv"));if(fc.showSaveDialog(this)!=JFileChooser.APPROVE_OPTION)return;File f=fc.getSelectedFile();if(f.exists()&&JOptionPane.showConfirmDialog(this,"Overwrite existing file?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(f),StandardCharsets.UTF_8))){w.println("ID,Medicine Name,Company,Batch,Quantity,Price,Expiry Date,Minimum Stock,Status");for(Medicine m:data)w.println(csv(m.getId())+","+csv(m.getName())+","+csv(m.getCompany())+","+csv(m.getBatchNo())+","+m.getQuantity()+","+m.getPrice()+","+csv(m.getExpiryDate())+","+m.getMinStock()+","+csv(status(m)));statusLine.setText("  Exported inventory to "+f.getName());message("Export successful:\n"+f.getAbsolutePath());}catch(IOException e){message("Export failed: "+e.getMessage());}}
 private String csv(String s){return "\""+s.replace("\"","\"\"")+"\"";}private void reload(){try{ArrayList<Medicine> loaded=FileManager.load();data.clear();data.addAll(loaded);refresh();statusLine.setText("  Reloaded saved records");}catch(Exception e){message("Could not reload saved data: "+e.getMessage());}}
 private void save(){try{FileManager.save(data);refresh();statusLine.setText("  Changes saved automatically");}catch(IOException e){message("Could not save data. Check folder permissions.\n"+e.getMessage());}}
 private void message(String s){JOptionPane.showMessageDialog(this,s,"MediTrack",JOptionPane.INFORMATION_MESSAGE);}
 private class StatusRenderer extends DefaultTableCellRenderer{public Component getTableCellRendererComponent(JTable t,Object v,boolean sel,boolean focus,int row,int col){JLabel l=(JLabel)super.getTableCellRendererComponent(t,v,sel,focus,row,col);l.setHorizontalAlignment(col==7?CENTER:LEFT);l.setBorder(new EmptyBorder(4,7,4,7));if(col==7&&!sel){String s=String.valueOf(v);Color fg=s.equals("EXPIRED")?new Color(186,43,55):s.equals("EXPIRING SOON")?new Color(163,102,13):s.equals("LOW STOCK")?new Color(106,69,177):new Color(34,130,91);Color b=s.equals("EXPIRED")?new Color(255,235,237):s.equals("EXPIRING SOON")?new Color(255,246,222):s.equals("LOW STOCK")?new Color(244,237,255):new Color(230,248,239);l.setForeground(fg);l.setBackground(b);l.setFont(new Font("SansSerif",Font.BOLD,10));}else if(!sel){l.setBackground(Color.WHITE);l.setForeground(navy);}return l;}}
 public static void main(String[] args){try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){}SwingUtilities.invokeLater(()->new Main().setVisible(true));}
